"""Embed the Word minutes templates and the PowerPoint project template as base64 scripts.

The website loads templates from that script because some hosts (claude.ai) can't serve
.docx files. Run after editing either template:  python3 scripts/embed-templates.py
"""
import base64, json, pathlib

root = pathlib.Path(__file__).resolve().parent.parent / 'assets' / 'templates'
data = {c: base64.b64encode((root / f'minutes-{c}.docx').read_bytes()).decode() for c in ('national', 'ministry')}
(root / 'minutes-template.js').write_text(
    '// Generated by scripts/embed-templates.py from minutes-national.docx and minutes-ministry.docx. Do not edit by hand.\n'
    f'window.AAI_MINUTES_TEMPLATES = {json.dumps(data)};\n')
print('wrote', root / 'minutes-template.js')
(root / 'project-template.js').write_text(
    '// Generated by scripts/embed-templates.py from project-template.pptx. Do not edit by hand.\n'
    f"window.AAI_PROJECT_TEMPLATE = '{base64.b64encode((root / 'project-template.pptx').read_bytes()).decode()}';\n")
print('wrote', root / 'project-template.js')
